sed -i '/val translateLauncher =/a \            val universalLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->\n                uri?.let {\n                    context.contentResolver.takePersistableUriPermission(it, Intent.FLAG_GRANT_READ_URI_PERMISSION)\n                    viewModel.saveSetting("BG_UNIVERSAL", it.toString())\n                }\n            }' android_app/app/src/main/java/com/aidict/app/ui/screens/SettingsScreen.kt

sed -i '/val bgDict by viewModel.bgDict.collectAsState()/a \        val bgUniversal by viewModel.bgUniversal.collectAsState()' android_app/app/src/main/java/com/aidict/app/ui/screens/SettingsScreen.kt

sed -i '/Text("Dict Mode BG")/i \            Row(modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {\n                Text("Universal BG (Fallback)")\n                Button(onClick = { universalLauncher.launch(arrayOf("image/*")) }) { Text(if (bgUniversal == null) "Select" else "Change") }\n                if (bgUniversal != null) IconButton(onClick = { viewModel.saveSetting("BG_UNIVERSAL", "") }) { Icon(Icons.Default.Delete, "Clear") }\n            }' android_app/app/src/main/java/com/aidict/app/ui/screens/SettingsScreen.kt

sed -i '/val quotes = listOf("None", "Shuffle",/a \            val quoteStyle by viewModel.quoteStyle.collectAsState()\n            val styles = listOf("Serif", "Sans Serif", "Monospace", "Cursive")\n            com.aidict.app.ui.components.SearchableDropdown(\n                label = "Quote Style",\n                currentValue = quoteStyle,\n                options = styles,\n                onSelected = { viewModel.saveSetting("QUOTE_STYLE", it) }\n            )' android_app/app/src/main/java/com/aidict/app/ui/screens/SettingsScreen.kt

